-- Index for ORDER BY createdAt DESC (used on every list query)
CREATE INDEX IF NOT EXISTS idx_leads_createdAt ON leads (createdAt DESC);

-- Index for stage filter (pipeline + list filter)
CREATE INDEX IF NOT EXISTS idx_leads_stage ON leads (stage);

-- Index for assignedTo filter
CREATE INDEX IF NOT EXISTS idx_leads_assignedTo ON leads (assignedTo);

-- Index for leadSource filter
CREATE INDEX IF NOT EXISTS idx_leads_leadSource ON leads (leadSource);

-- Index for interestedProgram filter
CREATE INDEX IF NOT EXISTS idx_leads_interestedProgram ON leads (interestedProgram);

-- Index for metaCampaign filter
CREATE INDEX IF NOT EXISTS idx_leads_metaCampaign ON leads (metaCampaign);

-- Index for metaFormId filter
CREATE INDEX IF NOT EXISTS idx_leads_metaFormId ON leads (metaFormId);

-- Index for duplicate check on phone/email/whatsapp
CREATE INDEX IF NOT EXISTS idx_leads_phone ON leads (phone);
CREATE INDEX IF NOT EXISTS idx_leads_email ON leads (email);
CREATE INDEX IF NOT EXISTS idx_leads_whatsapp ON leads (whatsapp);

